# Mapping emoji → identifiant
EMOJI_TO_ICON = {
    "📚": "book",
    "💼": "briefcase",
    "💻": "code",
    "🚀": "rocket",
    "🛒": "cart",
    "🏠": "home",
    "💰": "coin",
    "❤️": "heart",
    "🏃": "run",
    "🍽️": "utensils",
    "✈️": "plane",
    "👨‍👩‍👧": "family",
    "👥": "users",
    "📞": "phone",
    "📧": "mail",
    "📅": "calendar",
    "🎯": "target",
    "📖": "book-open",
    "🎬": "film",
    "🎵": "music",
    "🛠️": "wrench",
    "🐶": "paw",
    "🚗": "car",
    "📂": "folder",
    "🧹": "broom",
    "🎉": "party",
    "💡": "bulb",
    "🔔": "bell",
    "🛍️": "bag",
    "🌱": "seedling",
}


@register.simple_tag
def render_icon(icon_name, size=18):
    svg = ICONS.get(icon_name, "")
    if svg and size != 18:
        svg = svg.replace('width="18"', f'width="{size}"')
        svg = svg.replace('height="18"', f'height="{size}"')
    return mark_safe(svg)


@register.filter
def emoji_to_icon(emoji):
    return EMOJI_TO_ICON.get(emoji, "book")
